"""Parse legacy bank statements exported as .xls (Excel 97-2003) into a normalized CSV.

The bank still exports the old binary format; highlighted rows (yellow fill) are pending transactions.
"""

import csv
import sys
from datetime import datetime

import xlrd

YELLOW = (255, 255, 0)


def is_pending(book, sheet, row, col=0):
    xf = book.xf_list[sheet.cell_xf_index(row, col)]
    colour = book.colour_map.get(xf.background.pattern_colour_index)
    return colour == YELLOW


def read_statement(path):
    book = xlrd.open_workbook(path, formatting_info=True)
    sheet = book.sheet_by_index(0)
    header_row = next(r for r in range(sheet.nrows) if sheet.cell_value(r, 0) == "Fecha")
    rows = []
    for r in range(header_row + 1, sheet.nrows):
        raw_date = sheet.cell(r, 0)
        if raw_date.ctype != xlrd.XL_CELL_DATE:
            continue  # footer / totals
        rows.append({
            "date": datetime(*xlrd.xldate_as_tuple(raw_date.value, book.datemode)).date().isoformat(),
            "description": sheet.cell_value(r, 1).strip(),
            "amount": round(float(sheet.cell_value(r, 3) or 0) - float(sheet.cell_value(r, 2) or 0), 2),
            "pending": is_pending(book, sheet, r),
        })
    return rows


def main(paths):
    writer = csv.DictWriter(sys.stdout, fieldnames=["file", "date", "description", "amount", "pending"])
    writer.writeheader()
    for path in paths:
        try:
            for row in read_statement(path):
                writer.writerow({"file": path, **row})
        except xlrd.XLRDError as exc:
            print(f"{path}: {exc}", file=sys.stderr)
        except StopIteration:
            print(f"{path}: header row not found", file=sys.stderr)


if __name__ == "__main__":
    main(sys.argv[1:])

"""Translate candidate open reading frames to protein and report GC content per sequence.

Input: a TSV with `id<TAB>sequence` (one DNA sequence per line). Output: JSON lines.
"""

import argparse
import json
import sys

from seqtranslate import CodonTable, DnaSequence

MIN_PROTEIN_LEN = 30


def longest_orf(seq, table):
    """Longest protein over the six reading frames (stop codons split the frames)."""
    best = ""
    for strand in (seq, seq.reverse_complement()):
        for frame in range(3):
            protein = strand[frame:].translate(table=table, to_stop=False)
            for chunk in str(protein).split("*"):
                start = chunk.find("M")
                if start != -1 and len(chunk) - start > len(best):
                    best = chunk[start:]
    return best


def process(line, table):
    seq_id, raw = line.rstrip("\n").split("\t", 1)
    seq = DnaSequence(raw.upper(), strict=False)
    protein = longest_orf(seq, table)
    return {
        "id": seq_id,
        "length": len(seq),
        "gc": round(seq.gc_fraction() * 100, 2),
        "orf_length": len(protein),
        "protein": protein if len(protein) >= MIN_PROTEIN_LEN else None,
    }


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("tsv", type=argparse.FileType("r"), nargs="?", default=sys.stdin)
    parser.add_argument("--table", type=int, default=11, help="NCBI genetic code (11 = bacterial)")
    args = parser.parse_args()

    table = CodonTable.by_ncbi_id(args.table)
    for line in args.tsv:
        if not line.strip() or line.startswith("#"):
            continue
        try:
            print(json.dumps(process(line, table)))
        except ValueError as exc:
            print(f"skipping line: {exc}", file=sys.stderr)


if __name__ == "__main__":
    main()
